const dashboardMarkup = pageContent.innerHTML;
const apiBase = window.__AMORA_API_BASE__ || (window.location.protocol === 'file:' ? 'http://localhost:4016/api' : '/api');
let apiToken = sessionStorage.getItem('amora_token') || localStorage.getItem('amora_token') || '';
let firebaseUser = null;
let loginInFlight = false;
let currentCart = [];
const labels = { dashboard: 'Overview', 'inventory-analysis': 'Inventory analysis', inventory: 'Inventory', categories: 'Categories & brands', batches: 'Batch management', sales: 'Sales & billing', 'sales-history': 'Sales history', 'sales-returns': 'Sales returns', purchases: 'Purchases', 'purchase-returns': 'Purchase returns', suppliers: 'Suppliers', expiry: 'Expiry watch', reports: 'Reports', 'profit-loss': 'AI profit & loss', forecast: 'AI forecasting', team: 'Team', customers: 'Customers', notifications: 'Notifications', assistant: 'AI assistant', activity: 'Activity logs', settings: 'Settings' };
const products = [
  ['Amul Taaza Milk', 'Dairy & Bakery', 'DAB-001', '₹68', '184', 'Low stock', 'https://images.unsplash.com/photo-1563636619-e9143da7973b?w=120&h=120&fit=crop'],
  ['India Gate Basmati Rice', 'Grocery & Staples', 'GRC-024', '₹645', '42', 'Healthy', 'https://images.unsplash.com/photo-1586201375761-83865001e31c?w=120&h=120&fit=crop'],
  ['Fortune Sunflower Oil', 'Grocery & Staples', 'GRC-031', '₹142', '76', 'Healthy', 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=120&h=120&fit=crop'],
  ['Lay\'s Magic Masala', 'Snacks & Chocolates', 'SNC-118', '₹20', '12', 'Low stock', 'https://images.unsplash.com/photo-1566478989037-eec170784d0b?w=120&h=120&fit=crop'],
  ['Tata Tea Gold', 'Beverages', 'BEV-043', '₹285', '96', 'Healthy', 'https://images.unsplash.com/photo-1597318181409-cf64d0b5d8a2?w=120&h=120&fit=crop'],
  ['Surf Excel Matic', 'Cleaning Supplies', 'CLN-055', '₹410', '0', 'Out of stock', 'https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=120&h=120&fit=crop']
];

function showToast(message) { toast.textContent = message; toast.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => toast.classList.remove('show'), 2600); }
async function clearAuthenticatedState() { if (firebaseUser) await logoutFromFirebase(); firebaseUser = null; apiToken = ''; currentCart = []; sessionStorage.removeItem('amora_token'); localStorage.removeItem('amora_token'); pageContent.innerHTML = ''; document.querySelector('.app-shell').classList.add('auth-locked'); document.getElementById('authScreen').hidden = false; }
async function apiRequest(path, options = {}) { const token = firebaseUser ? await firebaseUser.getIdToken() : apiToken; const response = await fetch(`${apiBase}${path}`, { ...options, headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(options.headers || {}) } }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error || 'Request failed'); return payload; }
async function connectBackend() { try { if (!apiToken && !firebaseUser) throw new Error('login required'); const dashboard = await apiRequest('/dashboard'); if (!pageContent.innerHTML.trim()) emptyDashboard(); const cards = document.querySelectorAll('.metric-card > strong'); if (cards.length >= 4) { cards[0].textContent = `₹${Number(dashboard.metrics.revenue).toLocaleString('en-IN')}`; cards[1].textContent = Number(dashboard.metrics.stock).toLocaleString('en-IN'); cards[2].textContent = String(dashboard.lowStock.length).padStart(2, '0'); cards[3].textContent = Number(dashboard.metrics.products).toLocaleString('en-IN'); } const notificationCount = document.querySelector('.nav-item[data-view="notifications"] .nav-count'); if (notificationCount) notificationCount.textContent = dashboard.metrics.notifications; document.querySelector('.app-shell').classList.remove('auth-locked'); document.getElementById('authScreen').hidden = true; document.body.dataset.backend = 'connected'; } catch (error) { document.body.dataset.backend = 'offline'; if (error.message === 'Authentication required' || error.message === 'Invalid or expired session' || error.message.includes('403')) await clearAuthenticatedState(); else document.getElementById('authScreen').hidden = false; if (firebaseUser && error.message.includes('Invalid or expired')) showToast('Firebase Admin verification is not configured on the server.'); } }
let inactivityTimer;
async function logout(force = false) { if (!force && !window.confirm('Log out of AMORA?')) return; await clearAuthenticatedState(); showToast('You have been securely logged out.'); }
function resetInactivityTimer() { clearTimeout(inactivityTimer); if (apiToken) inactivityTimer = setTimeout(() => logout(true), 30 * 60 * 1000); }
function escapeHtml(value = '') { return String(value ?? '').replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character])); }
function actionButton(label, kind = 'primary', action = '') { return `<button class="button ${kind === 'primary' ? 'primary-button' : 'secondary-button'}" data-action="${action}">${label}</button>`; }
function pageHeader(eyebrow, title, copy, actions = '') { return `<div class="page-heading"><div><p class="eyebrow">${escapeHtml(eyebrow)}</p><h1>${escapeHtml(title)}</h1><p class="subheading">${escapeHtml(copy)}</p></div><div class="heading-actions">${actions}</div></div>`; }
function table(rows, headings) { return `<div class="table-scroll"><table><thead><tr>${headings.map((heading) => `<th>${escapeHtml(heading)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`; }
function row(cells) { return `<tr>${cells.map((cell) => `<td>${cell}</td>`).join('')}</tr>`; }
function bindDashboard() {
  document.getElementById('saleButton').addEventListener('click', () => setView('sales'));
  document.getElementById('receiveButton').addEventListener('click', () => setView('purchases'));
  document.getElementById('productButton').addEventListener('click', () => setView('inventory'));
  document.getElementById('exportButton').addEventListener('click', () => showToast('Your overview report is being prepared.'));
  document.getElementById('salesPeriod').addEventListener('change', (event) => loadSalesChart(event.target.value));
  if (apiToken || firebaseUser) loadSalesChart('weekly');
}
async function loadSalesChart(period) { try { const data = await apiRequest(`/reports/sales-trend?period=${period}`); const points = data.rows.length ? data.rows : [{ revenue: 0 }]; const width = 720; const height = 205; const max = Math.max(...points.map((point) => Number(point.revenue)), 1); const coords = points.map((point, index) => `${points.length === 1 ? width : (index / (points.length - 1)) * width},${height - (Number(point.revenue) / max) * 170}`); const line = `M${coords.join(' L')}`; document.getElementById('salesChartLine').setAttribute('d', line); document.getElementById('salesChartArea').setAttribute('d', `${line} L720 230 L0 230Z`); const last = coords.at(-1).split(','); document.getElementById('salesChartDot').setAttribute('cx', last[0]); document.getElementById('salesChartDot').setAttribute('cy', last[1]); document.getElementById('salesChartCaption').textContent = period === 'monthly' ? 'Revenue performance for the last 30 days' : 'Revenue performance for the last 7 days'; const labels = document.getElementById('salesChartLabels'); labels.innerHTML = points.slice(-7).map((point) => `<span>${point.date ? new Date(`${point.date}T00:00:00`).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' }) : 'Today'}</span>`).join(''); } catch (error) { showToast(error.message); } }
function emptyDashboard() { pageContent.innerHTML = dashboardMarkup; bindDashboard(); }

async function refreshDashboardMetrics() { try { const dashboard = await apiRequest('/dashboard'); const cards = document.querySelectorAll('.metric-card > strong'); if (cards.length >= 4) { cards[1].textContent = Number(dashboard.metrics.stock).toLocaleString('en-IN'); cards[2].textContent = String(dashboard.lowStock.length).padStart(2, '0'); cards[3].textContent = Number(dashboard.metrics.products).toLocaleString('en-IN'); } const count = document.querySelector('.nav-item[data-view="inventory"] .nav-count'); if (count) count.textContent = dashboard.metrics.products; const notificationCount = document.querySelector('.nav-item[data-view="notifications"] .nav-count'); if (notificationCount) notificationCount.textContent = dashboard.metrics.notifications; } catch {} }
async function inventoryView() {
  pageContent.innerHTML = `${pageHeader('Inventory management', 'Products & stock', 'Manage your live catalogue, pricing, stock thresholds and product details.', `${actionButton('＋ Add product', 'primary', 'add-product')}`)}<div class="filter-bar"><input class="field" id="productSearch" placeholder="Search name, SKU or barcode"><select class="field" id="productCategory"><option value="">All categories</option></select><select class="field" id="productStatus"><option value="">All stock status</option><option value="low_stock">Low stock</option><option value="out_of_stock">Out of stock</option></select><select class="field" id="productSort"><option value="name">Sort: Name</option><option value="sku">Sort: SKU</option><option value="selling_price">Sort: Price</option><option value="available_quantity">Sort: Stock</option></select></div><div id="productWorkspace"><div class="empty-state">Loading live products...</div></div>`;
  pageContent.insertAdjacentHTML('beforeend', '<section class="panel stock-actions-panel"><div class="panel-header"><div><h2>Stock operations</h2><p>Every movement is recorded with an authenticated audit trail.</p></div></div><div class="stock-actions"><button class="button secondary-button" data-action="stock-in">Stock in</button><button class="button secondary-button" data-action="stock-out">Stock out</button><button class="button secondary-button" data-action="stock-adjust">Adjust stock</button><button class="button secondary-button" data-action="stock-transfer">Transfer stock</button></div></section><section class="panel table-panel"><div class="panel-header"><div><h2>Movement history</h2><p>Live stock transactions for this store.</p></div></div><div id="movementWorkspace"><div class="empty-state">Loading movement history...</div></div></section>');
  const [categoryData] = await Promise.all([apiRequest('/categories')]);
  const categorySelect = document.getElementById('productCategory'); categoryData.forEach((category) => { categorySelect.insertAdjacentHTML('beforeend', `<option value="${category.id}">${escapeHtml(category.name)}</option>`); });
  let page = window.productPage || 1;
  async function loadProducts(nextPage = page) { page = nextPage; const query = new URLSearchParams({ search: document.getElementById('productSearch').value, categoryId: categorySelect.value, status: document.getElementById('productStatus').value, sort: document.getElementById('productSort').value, page: String(page), pageSize: '10' }); const data = await apiRequest(`/products?${query}`); const rows = data.rows.map((item) => { const status = item.available_quantity <= 0 ? 'Out of stock' : item.available_quantity <= item.min_stock ? 'Low stock' : 'Healthy'; return row([`<button class="product-link" data-action="view-product" data-product-id="${item.id}"><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.sku)}${item.barcode ? ` · ${escapeHtml(item.barcode)}` : ''}</small></button>`, escapeHtml(item.category || 'Uncategorized'), `₹${Number(item.selling_price).toLocaleString('en-IN')}`, item.available_quantity, `<span class="status ${status === 'Healthy' ? 'paid' : 'warning-status'}">${status}</span>`, `<button class="table-action" data-action="edit-product" data-product-id="${item.id}">Edit</button> <button class="table-action danger-action" data-action="delete-product" data-product-id="${item.id}">Delete</button>`]); }); const pages = Math.max(1, Math.ceil(data.total / data.pageSize)); document.getElementById('productWorkspace').innerHTML = `<section class="panel table-panel">${rows.length ? table(rows, ['Product', 'Category', 'Selling price', 'Available', 'Status', 'Action']) : '<div class="empty-state">No products match these filters.</div>'}<div class="pagination"><button class="table-action" data-action="product-page" data-page="${page - 1}" ${page <= 1 ? 'disabled' : ''}>Previous</button><span>Page ${page} of ${pages}</span><button class="table-action" data-action="product-page" data-page="${page + 1}" ${page >= pages ? 'disabled' : ''}>Next</button></div></section>`; }
  ['productSearch', 'productCategory', 'productStatus', 'productSort'].forEach((id) => document.getElementById(id).addEventListener('input', () => { window.productPage = 1; loadProducts(1); }));
  async function loadMovementHistory() { const data = await apiRequest('/inventory'); const rows = data.movements.map((item) => row([`<strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.type)}</small>`, item.quantity, `${item.previous_quantity} → ${item.updated_quantity}`, escapeHtml(item.performed_by || 'System'), escapeHtml(item.reason || 'Not specified'), new Date(item.created_at).toLocaleString('en-IN')])); document.getElementById('movementWorkspace').innerHTML = rows.length ? table(rows, ['Product / type', 'Quantity', 'Stock change', 'User', 'Reason', 'Date']) : '<div class="empty-state">No stock movements recorded.</div>'; }
  await Promise.all([loadProducts(), loadMovementHistory()]);
}
function stockForm(type, products) { const labelsByType = { 'stock-in': ['Stock in', 'STOCK_IN'], 'stock-out': ['Stock out', 'STOCK_OUT'], 'stock-adjust': ['Adjust stock', 'MANUAL_ADJUSTMENT'], 'stock-transfer': ['Transfer stock', 'TRANSFER_OUT'] }; const [title] = labelsByType[type]; const options = products.map((product) => `<option value="${product.id}">${escapeHtml(product.name)} · ${escapeHtml(product.sku)}</option>`).join(''); return `<section class="panel product-form-panel"><div class="panel-header"><div><h2>${title}</h2><p>This transaction is atomic and cannot be submitted twice.</p></div><button class="text-button" data-action="close-stock-form">Close</button></div><form id="stockForm" data-stock-type="${type}" class="product-form"><div class="form-grid"><label>Product<select class="field" name="product_id" required>${options}</select></label>${type === 'stock-transfer' ? `<label>Destination product<select class="field" name="destination_product_id" required>${options}</select></label>` : ''}<label>Quantity<input class="field" name="quantity" type="number" ${type === 'stock-adjust' ? 'step="0.01"' : 'min="0.01" step="0.01"'} ${type === 'stock-adjust' ? 'placeholder="Use a negative number to reduce stock"' : ''} required></label>${type === 'stock-in' ? '<label>Batch number<input class="field" name="batch_number" required></label><label>Expiry date<input class="field" name="expiry_date" type="date"></label><label>Purchase price<input class="field" name="purchase_price" type="number" min="0" step="0.01" value="0"></label>' : ''}${type === 'stock-out' ? '<label>Transaction type<select class="field" name="movement_type"><option value="STOCK_OUT">Stock out</option><option value="DAMAGE_OUT">Damaged stock</option></select></label>' : ''}</div><label>Reason<input class="field" name="reason" minlength="3" required></label><input type="hidden" name="transaction_key" value="ui-${crypto.randomUUID()}"><p class="auth-error" id="stockFormError"></p><button class="button primary-button" type="submit">Record ${title.toLowerCase()}</button></form></section>`; }
async function openStockForm(type) { const data = await apiRequest('/products?pageSize=100'); pageContent.innerHTML = stockForm(type, data.rows); }
async function submitStockForm(form) { const data = Object.fromEntries(new FormData(form).entries()); const type = form.dataset.stockType; const quantity = Number(data.quantity); const body = { ...data, product_id: Number(data.product_id), quantity, transaction_key: data.transaction_key }; let path = `/inventory/${type === 'stock-in' ? 'stock-in' : type === 'stock-out' ? 'stock-out' : type === 'stock-transfer' ? 'transfer' : 'adjust'}`; if (type === 'stock-in') { body.purchase_price = Number(data.purchase_price); } if (type === 'stock-out') body.type = data.movement_type; if (type === 'stock-adjust' && quantity > 0) body.quantity = quantity; if (type === 'stock-transfer') body.destination_product_id = Number(data.destination_product_id); await apiRequest(path, { method: 'POST', body: JSON.stringify(body) }); showToast('Stock movement recorded.'); await refreshDashboardMetrics(); setView('inventory'); }
async function supplierView() { pageContent.innerHTML = `${pageHeader('Procurement', 'Suppliers', 'Manage trusted vendors, product relationships, purchase history and payables.', actionButton('＋ Add supplier', 'primary', 'add-supplier'))}<div class="filter-bar"><input class="field" id="supplierSearch" placeholder="Search supplier, code or contact"><select class="field" id="supplierStatus"><option value="">Active suppliers</option><option value="archived">Archived suppliers</option><option value="all">All suppliers</option></select><select class="field" id="supplierSort"><option value="name">Sort: Name</option><option value="code">Sort: Code</option><option value="payable">Sort: Outstanding payable</option><option value="purchases">Sort: Purchase value</option></select></div><div id="supplierWorkspace"><div class="empty-state">Loading live suppliers...</div></div>`; async function load() { const query = new URLSearchParams({ search: document.getElementById('supplierSearch').value, status: document.getElementById('supplierStatus').value, sort: document.getElementById('supplierSort').value }); const suppliers = await apiRequest(`/suppliers?${query}`); const rows = suppliers.map((supplier) => row([`<button class="product-link" data-action="view-supplier" data-supplier-id="${supplier.id}"><strong>${escapeHtml(supplier.name)}</strong><small>${escapeHtml(supplier.supplier_code)} · ${escapeHtml(supplier.contact_person || 'No contact')}</small></button>`, escapeHtml(supplier.phone), `${supplier.purchase_count} orders · ₹${Number(supplier.purchase_value).toLocaleString('en-IN')}`, `₹${Number(supplier.outstanding_payable).toLocaleString('en-IN')}`, `${supplier.mapped_products} products`, supplier.active ? '<span class="status paid">Active</span>' : '<span class="status warning-status">Archived</span>', `<button class="table-action" data-action="edit-supplier" data-supplier-id="${supplier.id}">Edit</button> <button class="table-action danger-action" data-action="archive-supplier" data-supplier-id="${supplier.id}" ${supplier.active ? '' : 'disabled'}>Archive</button>`])); document.getElementById('supplierWorkspace').innerHTML = `<section class="panel table-panel">${rows.length ? table(rows, ['Supplier', 'Phone', 'Purchase history', 'Outstanding', 'Products', 'Status', 'Action']) : '<div class="empty-state">No suppliers match these filters.</div>'}</section>`; } ['supplierSearch', 'supplierStatus', 'supplierSort'].forEach((id) => document.getElementById(id).addEventListener('input', load)); await load(); }
function supplierForm(supplier = null) { const editing = Boolean(supplier); const value = (key) => escapeHtml(supplier?.[key] ?? ''); return `<section class="panel product-form-panel"><div class="panel-header"><div><h2>${editing ? 'Edit supplier' : 'Add supplier'}</h2><p>Supplier records are validated and isolated to the current store.</p></div><button class="text-button" data-action="close-supplier-form">Close</button></div><form id="supplierForm" data-supplier-id="${editing ? supplier.id : ''}" class="product-form"><div class="form-grid"><label>Supplier code<input class="field" name="supplier_code" value="${value('supplier_code')}" required pattern="[A-Za-z0-9-]+"></label><label>Supplier name<input class="field" name="name" value="${value('name')}" required></label><label>Contact person<input class="field" name="contact_person" value="${value('contact_person')}"></label><label>Phone<input class="field" name="phone" value="${value('phone')}" required></label><label>Email<input class="field" name="email" type="email" value="${value('email')}" required></label><label>GSTIN<input class="field" name="gstin" value="${value('gstin')}"></label></div><label>Address<textarea class="field" name="address" rows="3">${value('address')}</textarea></label><p class="auth-error" id="supplierFormError"></p><button class="button primary-button" type="submit">${editing ? 'Save changes' : 'Create supplier'}</button></form></section>`; }
async function openSupplierForm(id = '') { const supplier = id ? await apiRequest(`/suppliers/${id}`) : null; pageContent.innerHTML = supplierForm(supplier); }
async function openSupplierDetail(id) { const supplier = await apiRequest(`/suppliers/${id}`); const products = await apiRequest('/products?pageSize=100'); pageContent.innerHTML = `${pageHeader('Procurement', supplier.name, `${supplier.supplier_code} · ${supplier.active ? 'Active supplier' : 'Archived supplier'}`, `<button class="button secondary-button" data-action="edit-supplier" data-supplier-id="${supplier.id}">Edit supplier</button>`)}<section class="supplier-detail-grid"><section class="panel product-detail"><div><strong>Contact person</strong><span>${escapeHtml(supplier.contact_person || 'Not set')}</span></div><div><strong>Phone</strong><span>${escapeHtml(supplier.phone)}</span></div><div><strong>Email</strong><span>${escapeHtml(supplier.email)}</span></div><div><strong>GSTIN</strong><span>${escapeHtml(supplier.gstin || 'Not applicable')}</span></div><div><strong>Address</strong><span>${escapeHtml(supplier.address || 'Not set')}</span></div><div><strong>Outstanding payable</strong><span>₹${Number(supplier.outstanding_payable).toLocaleString('en-IN')}</span></div></section><section class="panel product-form-panel"><div class="panel-header"><div><h2>Product mapping</h2><p>${supplier.products.length} mapped products</p></div></div><form id="supplierMappingForm" data-supplier-id="${supplier.id}" class="product-form"><label>Product<select class="field" name="product_id" required>${products.rows.map((product) => `<option value="${product.id}">${escapeHtml(product.name)} · ${escapeHtml(product.sku)}</option>`).join('')}</select></label><p class="auth-error" id="mappingFormError"></p><button class="button secondary-button" type="submit">Map product</button></form><div class="mapped-products">${supplier.products.length ? supplier.products.map((product) => `<span class="status paid">${escapeHtml(product.name)}</span>`).join(' ') : '<div class="empty-state">No products mapped yet.</div>'}</div></section></section><section class="panel table-panel"><div class="panel-header"><div><h2>Purchase history</h2><p>Orders and payment status from the live database.</p></div></div>${supplier.purchases.length ? table(supplier.purchases.map((purchase) => row([purchase.order_number, new Date(purchase.order_date).toLocaleDateString('en-IN'), purchase.status, purchase.payment_status, `₹${Number(purchase.total).toLocaleString('en-IN')}`])), ['Order', 'Date', 'Status', 'Payment', 'Total']) : '<div class="empty-state">No purchase history for this supplier.</div>'}</section>`; }
async function submitSupplierForm(form) { const payload = Object.fromEntries(new FormData(form).entries()); const id = form.dataset.supplierId; await apiRequest(id ? `/suppliers/${id}` : '/suppliers', { method: id ? 'PATCH' : 'POST', body: JSON.stringify(payload) }); showToast(id ? 'Supplier updated successfully.' : 'Supplier created successfully.'); setView('suppliers'); }
async function notificationView() { pageContent.innerHTML = `${pageHeader('Workspace', 'Notifications', 'Live inventory and purchasing alerts for the current store.', '<button class="button secondary-button" data-action="mark-all-notifications">Mark all read</button>')}<div class="filter-bar"><select class="field" id="notificationType"><option value="">All alert types</option><option value="LOW_STOCK">Low stock</option><option value="OUT_OF_STOCK">Out of stock</option><option value="OVERSTOCK">Overstock</option><option value="EXPIRY">Expiry</option><option value="PENDING_PURCHASE">Pending purchases</option></select><select class="field" id="notificationRead"><option value="">All states</option><option value="unread">Unread</option><option value="read">Read</option></select></div><div id="notificationWorkspace"><div class="empty-state">Loading alerts...</div></div>`; async function load() { const query = new URLSearchParams({ type: document.getElementById('notificationType').value, read: document.getElementById('notificationRead').value }); const notifications = await apiRequest(`/notifications?${query}`); const rows = notifications.map((item) => row([`<strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.message)}</small>`, `<span class="status ${item.severity === 'critical' ? 'warning-status' : item.severity === 'info' ? 'paid' : 'warning-status'}">${escapeHtml(item.type)}</span>`, new Date(item.created_at).toLocaleString('en-IN'), item.read ? '<span class="status paid">Read</span>' : '<span class="status warning-status">Unread</span>', `<button class="table-action" data-action="read-notification" data-notification-id="${item.id}" ${item.read ? 'disabled' : ''}>Mark read</button> <button class="table-action danger-action" data-action="dismiss-notification" data-notification-id="${item.id}">Dismiss</button>`])); document.getElementById('notificationWorkspace').innerHTML = rows.length ? `<section class="panel table-panel">${table(rows, ['Alert', 'Type', 'Time', 'State', 'Action'])}</section>` : '<section class="panel"><div class="empty-state">No notifications match these filters.</div></section>'; } ['notificationType', 'notificationRead'].forEach((id) => document.getElementById(id).addEventListener('input', load)); await load(); }
async function purchaseView() { pageContent.innerHTML = `${pageHeader('Procurement', 'Purchase orders', 'Create orders, receive goods and track live supplier payments.', actionButton('＋ New purchase order', 'primary', 'add-purchase'))}<div id="purchaseWorkspace"><div class="empty-state">Loading purchase history...</div></div>`; const orders = await apiRequest('/purchases'); const rows = orders.map((order) => row([`<button class="product-link" data-action="view-purchase" data-purchase-id="${order.id}"><strong>${escapeHtml(order.order_number)}</strong><small>${escapeHtml(order.supplier_name)}</small></button>`, new Date(order.order_date).toLocaleDateString('en-IN'), order.status, order.payment_status, `₹${Number(order.total).toLocaleString('en-IN')}`])); document.getElementById('purchaseWorkspace').innerHTML = `<section class="panel table-panel">${rows.length ? table(rows, ['Order', 'Date', 'Status', 'Payment', 'Total']) : '<div class="empty-state">No purchase orders yet.</div>'}</section>`; }
function purchaseForm(suppliers, products) { const supplierOptions = suppliers.map((supplier) => `<option value="${supplier.id}">${escapeHtml(supplier.name)} · ${escapeHtml(supplier.supplier_code)}</option>`).join(''); const productOptions = products.rows.map((product) => `<option value="${product.id}">${escapeHtml(product.name)} · ${escapeHtml(product.sku)}</option>`).join(''); const line = () => `<div class="form-grid purchase-line"><label>Product<select class="field" name="product_id" required>${productOptions}</select></label><label>Quantity<input class="field" name="quantity" type="number" min="0.01" step="0.01" required></label><label>Purchase price<input class="field" name="unit_price" type="number" min="0" step="0.01" required></label><label>GST %<input class="field" name="gst_rate" type="number" min="0" max="28" step="0.01" value="5" required></label></div>`; return `<section class="panel product-form-panel"><div class="panel-header"><div><h2>New purchase order</h2><p>Totals are calculated and stored with the order.</p></div><button class="text-button" data-action="close-purchase-form">Close</button></div><form id="purchaseForm" class="product-form"><div class="form-grid"><label>Supplier<select class="field" name="supplier_id" required>${supplierOptions}</select></label><label>Expected date<input class="field" name="expected_date" type="date"></label><label>Discount<input class="field" name="discount" type="number" min="0" step="0.01" value="0"></label></div><div id="purchaseLines">${line()}${line()}</div><button class="button secondary-button" type="button" data-action="add-purchase-line">Add product line</button><input type="hidden" name="transaction_key" value="ui-po-${crypto.randomUUID()}"><p class="auth-error" id="purchaseFormError"></p><button class="button primary-button" type="submit">Create purchase order</button></form></section>`; }
async function openPurchaseForm() { const [suppliers, products] = await Promise.all([apiRequest('/suppliers'), apiRequest('/products?pageSize=100')]); pageContent.innerHTML = purchaseForm(suppliers, products); }
async function openPurchaseDetail(id) { const order = await apiRequest(`/purchases/${id}`); pageContent.innerHTML = `${pageHeader('Procurement', order.order_number, `${escapeHtml(order.supplier_name)} · ${order.status}`, actionButton('Back to purchases', 'secondary', 'close-purchase-form'))}<section class="panel table-panel">${table(order.items.map((item) => row([`${escapeHtml(item.name)}<small>${escapeHtml(item.sku)}</small>`, item.quantity, item.received_quantity, `₹${Number(item.unit_price).toLocaleString('en-IN')}`, `${item.gst_rate}%`])), ['Product', 'Ordered', 'Received', 'Unit price', 'GST'])}</section>${order.status !== 'received' && order.status !== 'cancelled' ? `<section class="panel product-form-panel"><div class="panel-header"><div><h2>Receive goods</h2><p>Receiving increases live stock atomically.</p></div></div><form id="receiptForm" data-purchase-id="${order.id}" class="product-form"><div id="receiptLines">${order.items.filter((item) => item.received_quantity < item.quantity).map((item) => `<div class="form-grid receipt-line" data-product-id="${item.product_id}"><label>${escapeHtml(item.name)}<input class="field" name="received_quantity" type="number" min="0.01" max="${item.quantity - item.received_quantity}" step="0.01" required></label><label>Batch number<input class="field" name="batch_number" required></label><label>Expiry date<input class="field" name="expiry_date" type="date"></label><label>Purchase price<input class="field" name="purchase_price" type="number" min="0" step="0.01" value="${item.unit_price}" required></label></div>`).join('')}</div><input type="hidden" name="transaction_key" value="ui-receipt-${crypto.randomUUID()}"><p class="auth-error" id="receiptFormError"></p><button class="button primary-button" type="submit">Confirm receipt</button></form></section>` : ''}`; }
async function submitPurchaseForm(form) { const data = Object.fromEntries(new FormData(form).entries()); const lines = [...form.querySelectorAll('.purchase-line')].map((line) => ({ product_id: Number(line.querySelector('[name="product_id"]').value), quantity: Number(line.querySelector('[name="quantity"]').value), unit_price: Number(line.querySelector('[name="unit_price"]').value), gst_rate: Number(line.querySelector('[name="gst_rate"]').value) })); const result = await apiRequest('/purchases', { method: 'POST', body: JSON.stringify({ supplier_id: Number(data.supplier_id), expected_date: data.expected_date, discount: Number(data.discount), transaction_key: data.transaction_key, items: lines }) }); showToast(`Purchase order ${result.order_number} created.`); openPurchaseDetail(result.id); }
async function submitReceiptForm(form) { const data = Object.fromEntries(new FormData(form).entries()); const items = [...form.querySelectorAll('.receipt-line')].map((line) => ({ product_id: Number(line.dataset.productId), received_quantity: Number(line.querySelector('[name="received_quantity"]').value), batch_number: line.querySelector('[name="batch_number"]').value, expiry_date: line.querySelector('[name="expiry_date"]').value, purchase_price: Number(line.querySelector('[name="purchase_price"]').value) })); await apiRequest(`/purchases/${form.dataset.purchaseId}/receive`, { method: 'POST', body: JSON.stringify({ transaction_key: data.transaction_key, items }) }); showToast('Goods received and stock updated.'); openPurchaseDetail(form.dataset.purchaseId); }
function salesView() { pageContent.innerHTML = `${pageHeader('Sales management', 'POS billing', 'Build a live sale with stock validation, tax, discounts and payment status.', actionButton('Complete sale', 'primary', 'complete-sale'))}<section class="panel pos-products"><div class="panel-header"><div><h2>Live product catalogue</h2><p>Select products from the current store inventory.</p></div></div><input class="field full-field" id="liveSaleSearch" placeholder="Search products"><div class="pos-product-grid" id="liveSaleProducts"><div class="empty-state">Loading products...</div></div></section><section class="panel cart-panel"><div class="panel-header"><div><h2>Current bill</h2><p id="cartCount">0 items</p></div><button class="text-button" data-action="clear-cart">Clear</button></div><div class="cart-items" id="cartItems"><div class="empty-state">Add products to start a sale.</div></div><div class="cart-summary"><label>Discount<input class="field full-field" id="saleDiscount" type="number" min="0" step="0.01" value="0"></label><select class="field full-field" id="salePayment"><option value="cash">Cash</option><option value="upi">UPI</option><option value="card">Card</option><option value="split">Split payment</option></select><div><span>Subtotal</span><strong id="cartSubtotal">₹0</strong></div><div><span>GST</span><strong id="cartTax">₹0</strong></div><div class="total"><span>Total payable</span><strong id="cartTotal">₹0</strong></div></div></section>`; const data = await apiRequest('/products?pageSize=100'); const render = (items) => { document.getElementById('liveSaleProducts').innerHTML = items.map((product) => `<button class="pos-product" data-live-product="${product.id}"><span><strong>${escapeHtml(product.name)}</strong><small>${escapeHtml(product.sku)} · ₹${Number(product.selling_price).toLocaleString('en-IN')} · ${product.available_quantity} in stock</small></span><b>+</b></button>`).join('') || '<div class="empty-state">No products found.</div>'; document.querySelectorAll('[data-live-product]').forEach((button) => button.addEventListener('click', () => { const product = data.rows.find((item) => item.id === Number(button.dataset.liveProduct)); currentCart.push({ id: product.id, product: [product.name, product.category, product.sku, `₹${product.selling_price}`, product.available_quantity, '', product.image_url] }); renderCart(); })); }; const renderCart = () => { document.getElementById('cartItems').innerHTML = currentCart.length ? currentCart.map((item) => `<div class="cart-row"><span>${escapeHtml(item.product[0])}<small>${item.product[3]}</small></span><b>${item.product[3]}</b></div>`).join('') : '<div class="empty-state">Add products to start a sale.</div>'; const subtotal = currentCart.reduce((sum, item) => sum + Number(item.product[3].replace('₹', '')), 0); const discount = Number(document.getElementById('saleDiscount').value || 0); const tax = subtotal * 0.05; document.getElementById('cartCount').textContent = `${currentCart.length} item${currentCart.length === 1 ? '' : 's'}`; document.getElementById('cartSubtotal').textContent = `₹${subtotal.toFixed(2)}`; document.getElementById('cartTax').textContent = `₹${tax.toFixed(2)}`; document.getElementById('cartTotal').textContent = `₹${Math.max(0, subtotal + tax - discount).toFixed(2)}`; }; document.getElementById('saleDiscount').addEventListener('input', renderCart); document.getElementById('liveSaleSearch').addEventListener('input', (event) => render(data.rows.filter((product) => `${product.name} ${product.sku} ${product.barcode || ''}`.toLowerCase().includes(event.target.value.toLowerCase())))); render(data.rows); window.renderSaleCart = renderCart; }
function productForm(product = null) { const editing = Boolean(product); const value = (key) => escapeHtml(product?.[key] ?? ''); return `<section class="panel product-form-panel"><div class="panel-header"><div><h2>${editing ? 'Edit product' : 'Add product'}</h2><p>Validated catalogue data is saved to AMORA's live database.</p></div><button class="text-button" data-action="close-product-form">Close</button></div><form id="productForm" data-product-id="${editing ? product.id : ''}" class="product-form"><div class="form-grid"><label>Product name<input class="field" name="name" value="${value('name')}" required></label><label>SKU<input class="field" name="sku" value="${value('sku')}" required></label><label>Barcode<input class="field" name="barcode" value="${value('barcode')}" required></label><label>Category<select class="field" name="category_id" required></select></label><label>Subcategory<input class="field" name="subcategory" value="${value('subcategory')}"></label><label>Brand<input class="field" name="brand" value="${value('brand')}"></label><label>Unit<input class="field" name="unit" value="${value('unit') || 'piece'}" required></label><label>Purchase price<input class="field" name="purchase_price" type="number" min="0" step="0.01" value="${value('purchase_price')}" required></label><label>Selling price<input class="field" name="selling_price" type="number" min="0" step="0.01" value="${value('selling_price')}" required></label><label>Minimum stock<input class="field" name="min_stock" type="number" min="0" step="1" value="${value('min_stock') || '10'}" required></label><label>Current stock<input class="field" name="current_stock" type="number" min="0" step="0.01" value="${editing ? value('available_quantity') : '0'}" ${editing ? 'readonly' : ''} required></label><label>Image URL (optional)<input class="field" name="image_url" type="url" value="${value('image_url')}"></label></div><label>Description<textarea class="field" name="description" rows="3">${value('description')}</textarea></label><p class="auth-error" id="productFormError"></p><button class="button primary-button" type="submit">${editing ? 'Save changes' : 'Create product'}</button></form></section>`; }
async function openProductForm(productId = '') { const [categories, product] = await Promise.all([apiRequest('/categories'), productId ? apiRequest(`/products/${productId}`) : Promise.resolve(null)]); pageContent.innerHTML = productForm(product); const select = document.querySelector('#productForm [name="category_id"]'); select.innerHTML = categories.map((category) => `<option value="${category.id}" ${product?.category_id === category.id ? 'selected' : ''}>${escapeHtml(category.name)}</option>`).join(''); }
async function submitProductForm(form) { const formData = new FormData(form); const payload = Object.fromEntries(formData.entries()); ['category_id', 'purchase_price', 'selling_price', 'min_stock', 'current_stock'].forEach((key) => { payload[key] = Number(payload[key]); }); const productId = form.dataset.productId; const response = await apiRequest(productId ? `/products/${productId}` : '/products', { method: productId ? 'PATCH' : 'POST', body: JSON.stringify(payload) }); showToast(productId ? 'Product updated successfully.' : `Product ${response.id} created successfully.`); await refreshDashboardMetrics(); setView('inventory'); }

