async function analysisView(kind) {
  const isProfit = kind === 'profit-loss';
  pageContent.innerHTML = `${pageHeader(isProfit ? 'AI & business intelligence' : 'Inventory intelligence', isProfit ? 'AI Profit & Loss Analysis' : 'Inventory Analysis', isProfit ? 'Reliable historical gross profit from batch cost, with AI-ready comparisons for future decisions.' : 'See what was purchased, sold, left on hand and what needs to be reordered.', `${['daily', 'monthly', 'yearly'].map((period) => `<button class="period-button ${period === 'monthly' ? 'selected' : ''}" data-period="${period}">${period[0].toUpperCase() + period.slice(1)}</button>`).join('')} ${actionButton('Export CSV', 'secondary', 'export-analysis')}`)}<div class="analysis-cards"><article class="analysis-card"><span>${isProfit ? 'Total revenue' : 'Stock in'}</span><strong id="analysisOne">₹0</strong><small>${isProfit ? 'Selling value' : 'Purchased units'}</small></article><article class="analysis-card"><span>${isProfit ? 'Total cost' : 'Stock out'}</span><strong id="analysisTwo">₹0</strong><small>${isProfit ? 'Weighted batch COGS' : 'Sold units'}</small></article><article class="analysis-card highlight"><span>${isProfit ? 'Gross profit' : 'Available'}</span><strong id="analysisThree">₹0</strong><small>${isProfit ? 'Revenue minus COGS' : 'Unexpired stock'}</small></article><article class="analysis-card"><span>${isProfit ? 'Gross margin' : 'Reorder'}</span><strong id="analysisFour">0%</strong><small>${isProfit ? 'Profit / revenue' : 'Products to replenish'}</small></article></div>${isProfit ? '<div class="analysis-visuals"><section class="panel visual-panel"><div class="panel-header"><div><h2>Revenue vs cost</h2><p>Accounts view for the selected period</p></div></div><div class="profit-pie" id="profitPie"><span>Gross margin</span><strong id="pieMargin">0%</strong></div><div class="pie-legend"><span><i class="revenue-dot"></i>Revenue</span><span><i class="cost-dot"></i>Cost</span></div></section><section class="panel visual-panel"><div class="panel-header"><div><h2>Product profit & loss</h2><p>Compare gross profit by product</p></div></div><div class="profit-bars" id="profitBars"></div></section></div>' : ''}<section class="panel table-panel"><div class="panel-header"><div><h2>${isProfit ? 'Product profitability' : 'Product movement analysis'}</h2><p>Calculated from AMORA transaction records</p></div><input class="field analysis-search" placeholder="Search product"></div><div id="analysisTable"><div class="empty-state">Loading live analysis...</div></div></section>`;
  async function load(period = 'monthly') { try { const data = await apiRequest(isProfit ? `/analysis/profit-loss?period=${period}` : `/analysis/inventory?period=${period}`); document.querySelectorAll('.period-button').forEach((button) => button.classList.toggle('selected', button.dataset.period === period)); if (isProfit) { document.getElementById('analysisOne').textContent = `₹${Number(data.summary.revenue).toLocaleString('en-IN')}`; document.getElementById('analysisTwo').textContent = `₹${Number(data.summary.cost).toLocaleString('en-IN')}`; document.getElementById('analysisThree').textContent = `₹${Number(data.summary.profit).toLocaleString('en-IN')}`; document.getElementById('analysisFour').textContent = `${data.summary.margin}%`; document.getElementById('pieMargin').textContent = `${data.summary.margin}%`; const revenueShare = data.summary.revenue ? Math.max(0, Math.min(100, (data.summary.cost / data.summary.revenue) * 100)) : 0; document.getElementById('profitPie').style.setProperty('--cost-share', `${revenueShare}%`); const maxProfit = Math.max(...data.rows.map((item) => Math.abs(item.profit)), 1); document.getElementById('profitBars').innerHTML = data.rows.map((item) => `<div class="profit-bar-row"><span>${escapeHtml(item.name)}</span><div><i class="${item.profit < 0 ? 'negative-bar' : ''}" style="width:${Math.max(4, Math.abs(item.profit) / maxProfit * 100)}%"></i></div><strong class="${item.profit < 0 ? 'loss' : 'gain'}">₹${Number(item.profit).toLocaleString('en-IN')}</strong></div>`).join(''); document.getElementById('analysisTable').innerHTML = table(data.rows.map((item) => row([`<strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.sku)}</small>`, `₹${Number(item.revenue).toLocaleString('en-IN')}`, `₹${Number(item.cost).toLocaleString('en-IN')}`, `<strong class="${item.profit < 0 ? 'loss' : 'gain'}">₹${Number(item.profit).toLocaleString('en-IN')}</strong>`, `${item.margin}%`])), ['Product', 'Revenue', 'Cost', 'Profit / loss', 'Margin']); } else { document.getElementById('analysisOne').textContent = Number(data.summary.purchased).toLocaleString('en-IN'); document.getElementById('analysisTwo').textContent = Number(data.summary.sold).toLocaleString('en-IN'); document.getElementById('analysisThree').textContent = Number(data.summary.remaining).toLocaleString('en-IN'); document.getElementById('analysisFour').textContent = data.summary.reorder; document.getElementById('analysisTable').innerHTML = table(data.rows.map((item) => row([`<strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.sku)} · ${escapeHtml(item.unit)}</small>`, item.purchased, item.sold, item.remaining, `<span class="status ${item.status === 'Healthy' ? 'paid' : 'warning-status'}">${escapeHtml(item.status)}</span>`, item.suggested_order])), ['Product', 'Purchased', 'Sold', 'Left', 'Status', 'Suggested order']); } } catch (error) { showToast(error.message); } }
  document.querySelectorAll('.period-button').forEach((button) => button.addEventListener('click', () => load(button.dataset.period))); await load();
}

