async function forecastView() {
  pageContent.innerHTML = `${pageHeader('Business intelligence', 'AI demand forecasting', 'Predicted inventory replenishment based on 30-day sales velocity.')}<div id="forecastWorkspace"><div class="empty-state">Loading demand forecast...</div></div>`;
  try {
    const data = await apiRequest('/forecast');
    const rows = data.map((item) => row([
      `<strong>${escapeHtml(item.name)}</strong>`,
      item.min_stock,
      `${item.units_sold} units`,
      `${item.daily_velocity} / day`,
      item.recommended_reorder > 0
        ? `<strong class="loss">Reorder ${item.recommended_reorder}</strong>`
        : '<span class="status paid">Adequate</span>'
    ]));
    document.getElementById('forecastWorkspace').innerHTML = rows.length
      ? `<section class="panel table-panel">${table(rows, ['Product', 'Min stock', '30-day sold', 'Daily velocity', 'Recommended order'])}</section>`
      : '<section class="panel"><div class="empty-state">No forecast data available.</div></section>';
  } catch (error) {
    showToast(error.message);
  }
}

