function setView(view) {
  const labelsForView = labels[view] || labels.dashboard;
  document.querySelectorAll('.nav-item[data-view]').forEach((item) => item.classList.toggle('active', item.dataset.view === view));
  pageTitle.textContent = labelsForView;
  sidebar.classList.remove('open');
  if (view === 'dashboard') return emptyDashboard();
  if (view === 'inventory-analysis' || view === 'profit-loss') return analysisView(view);
  if (view === 'inventory') return inventoryView();
  if (view === 'categories') return categoriesView();
  if (view === 'batches' || view === 'expiry') return expiryView();
  if (view === 'suppliers') return supplierView();
  if (view === 'purchases') return purchaseView();
  if (view === 'notifications') return notificationView();
  if (view === 'sales') return salesView();
  if (view === 'sales-history') return salesHistoryView();
  if (view === 'customers') return customersView();
  if (view === 'activity') return activityView();
  if (view === 'forecast') return forecastView();
  if (view === 'reports') return reportsView();
  if (view === 'assistant') return assistantView();
  if (view === 'settings') return settingsView();
  return genericView(view);
}
function bindPos() { currentCart = []; document.querySelectorAll('.pos-product').forEach((button) => button.addEventListener('click', () => { const product = products[Number(button.dataset.product)]; currentCart.push({ id: Number(button.dataset.product) + 1, product }); document.getElementById('cartItems').innerHTML = currentCart.map((item, index) => `<div class="cart-row"><span>${item.product[0]}<small>${item.product[3]} · batch tracked</small></span><b>${item.product[3]}</b><button data-remove="${index}">×</button></div>`).join(''); const subtotal = currentCart.reduce((total, item) => total + Number(item.product[3].replace('₹', '')), 0); document.getElementById('cartCount').textContent = `${currentCart.length} item${currentCart.length > 1 ? 's' : ''} · Walk-in customer`; document.getElementById('cartSubtotal').textContent = `₹${subtotal}`; document.getElementById('cartTax').textContent = `₹${Math.round(subtotal * 0.05)}`; document.getElementById('cartTotal').textContent = `₹${Math.round(subtotal * 1.05)}`; })); }

document.addEventListener('click', async (event) => {
  const viewTarget = event.target.closest('[data-view]');
  if (viewTarget) setView(viewTarget.dataset.view);
  const actionTarget = event.target.closest('[data-action]');
  if (actionTarget) {
    const action = actionTarget.dataset.action;
    if (action === 'logout') return logout();
    if (action === 'new-sale') return setView('sales');
    if (action === 'download-sales-csv') {
      try {
        const token = firebaseUser ? await firebaseUser.getIdToken() : apiToken;
        const res = await fetch(`${apiBase}/reports/export.csv?type=sales`, {
          headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}) }
        });
        if (!res.ok) throw new Error('Failed to generate sales CSV export.');
        const blob = await res.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `amora-sales-${new Date().toISOString().slice(0, 10)}.csv`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        window.URL.revokeObjectURL(url);
        showToast('Sales CSV exported successfully.');
      } catch (error) {
        showToast(error.message);
      }
      return;
    }
    if (action === 'complete-sale') {
      if (!currentCart.length) return showToast('Add a product before completing the sale.');
      try {
        const sale = await apiRequest('/sales', { method: 'POST', body: JSON.stringify({ payment_method: 'cash', items: currentCart.map((item) => ({ product_id: item.id, quantity: 1 })) }) });
        currentCart = [];
        showToast(`Sale ${sale.invoice_number} completed. Inventory updated.`);
      } catch (error) {
        showToast(error.message);
      }
      return;
    }
    if (action === 'export-analysis') return showToast('Analysis CSV export is ready from the Reports module.');
    const messages = { 'add-product': 'Product form opened with barcode and GST fields.', import: 'CSV import is ready for your product file.', 'edit-product': 'Product editor opened.', movement: 'Stock movement history opened.', reconcile: 'Physical stock count started.', hold: 'Bill held for later.', 'clear-cart': 'Current bill cleared.', 'open-form': 'Form opened with validation and approval rules.', open: 'Record details opened.', reorder: 'Smart reorder recommendations generated.', ask: 'I found 8 low-stock items, with 3 supplier recommendations.', 'edit-settings': 'Setting editor opened.', save: 'Settings saved successfully.' };
    showToast(messages[action] || 'Action completed.');
  }
});
