bindDashboard();
if (!apiToken && !firebaseUser) pageContent.innerHTML = '';
document.getElementById('loginForm').addEventListener('submit', async (event) => { event.preventDefault(); if (loginInFlight) return; loginInFlight = true; const submitButton = event.currentTarget.querySelector('button[type="submit"]'); submitButton.disabled = true; submitButton.setAttribute('aria-busy', 'true'); const error = document.getElementById('loginError'); error.textContent = ''; const email = document.getElementById('loginEmail').value; const password = document.getElementById('loginPassword').value; try { if (firebaseEnabled) { firebaseUser = await signInWithFirebase(email, password, document.getElementById('rememberMe').checked); apiToken = ''; if (!firebaseUser.emailVerified) showToast('Please verify your email address.'); } else { const session = await apiRequest('/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) }); apiToken = session.token; (document.getElementById('rememberMe').checked ? localStorage : sessionStorage).setItem('amora_token', apiToken); } await connectBackend(); resetInactivityTimer(); } catch (loginError) { firebaseUser = null; apiToken = ''; error.textContent = loginError.code === 'auth/too-many-requests' ? 'Too many unsuccessful attempts. Firebase has temporarily restricted sign-in. Please wait and try again later.' : loginError.message; } finally { loginInFlight = false; submitButton.disabled = false; submitButton.removeAttribute('aria-busy'); } });
document.getElementById('togglePassword').addEventListener('click', () => { const input = document.getElementById('loginPassword'); input.type = input.type === 'password' ? 'text' : 'password'; document.getElementById('togglePassword').textContent = input.type === 'password' ? 'Show' : 'Hide'; });
document.getElementById('forgotPassword').addEventListener('click', async () => { try { if (!firebaseEnabled) throw new Error('Password recovery requires Firebase Authentication setup.'); await resetFirebasePassword(document.getElementById('loginEmail').value); showToast('Password reset email sent.'); } catch (error) { showToast(error.message); } });
['click', 'keydown', 'mousemove', 'touchstart'].forEach((eventName) => document.addEventListener(eventName, resetInactivityTimer, { passive: true }));
if (firebaseEnabled) onAuthStateChanged((user) => { firebaseUser = user; document.getElementById('authStatus').textContent = user ? (user.emailVerified ? 'Firebase session restored.' : 'Firebase session restored; email verification is pending.') : 'Firebase is ready.'; if (user) connectBackend(); });
else document.getElementById('authStatus').textContent = 'Firebase is not configured; legacy local authentication is available.';
connectBackend();
